"const fs = require('fs');
const html = fs.readFileSync('scratch_bizno.html', 'utf8');

// Find meta description tag
const metaDescRegex = /<meta name="description"[^>]*>/i;
const metaDescMatch = html.match(metaDescRegex);
if (metaDescMatch) {
  console.log('=== Meta Description HTML ===');
  console.log(metaDescMatch[0]);
}

// Find og:description tag
const ogDescRegex = /<meta property="og:description"[^>]*>/i;
const ogDescMatch = html.match(ogDescRegex);
if (ogDescMatch) {
  console.log('\n=== OG Description HTML ===');
  console.log(ogDescMatch[0]);
}

// Find table row for employee count
const tableIdx = html.indexOf('<th>종업원수</th>');
if (tableIdx !== -1) {
  console.log('\n=== Table Content HTML ===');
  console.log(html.substring(tableIdx, tableIdx + 150));
}
