"const fs = require('fs');
const html = fs.readFileSync('scratch_bizno.html', 'utf8');

// Use cheerio-like simple regex/parser to extract content attribute
const getMetaContent = (nameOrProperty) => {
  const regex = new RegExp('<meta\\s+[^>]*(?:name|property)=\"' + nameOrProperty + '\"\\s+content=\"([^\"]*)\"', 'i');
  const match = html.match(regex);
  return match ? match[1] : 'Not Found';
};

console.log('=== name=\"description\" content ===');
console.log(getMetaContent('description'));

console.log('\n=== property=\"og:description\" content ===');
console.log(getMetaContent('og:description'));

console.log('\n=== Table Row HTML ===');
const tableIdx = html.indexOf('<th>종업원수</th>');
if (tableIdx !== -1) {
  console.log(html.substring(tableIdx, tableIdx + 200));
}
